sp_header_footer.client_script:
/* ==========================================================================
 * Enterprise Digital Portal — FOOTER client script
 * ==========================================================================
 * Header/footer scripts use `$scope` / `data`, never the `c.` alias.
 * The footer is presentational; the only behaviour is a defensive theme
 * fallback (in case the footer renders on a page where the header did not).
 * ========================================================================== */
api.controller = function ($scope, $window) {
    var THEME_ATTR = 'data-edp-theme';
    var THEME_KEY = 'edp-theme';

    var root = $window.document.documentElement;
    if (!root.getAttribute(THEME_ATTR)) {
        var stored = null;
        try {
            stored = $window.localStorage ? $window.localStorage.getItem(THEME_KEY) : null;
        } catch (storageErr) {
            stored = null;
        }
        if (stored !== 'light' && stored !== 'dark') {
            stored = ($window.matchMedia && $window.matchMedia('(prefers-color-scheme: dark)').matches)
                ? 'dark'
                : 'light';
        }
        root.setAttribute(THEME_ATTR, stored);
    }

    $scope.currentYear = new Date().getFullYear();
};

sp_header_footer.css:
/* ==========================================================================
 * Enterprise Digital Portal — FOOTER styles
 * ==========================================================================
 * Glass surface sitting on the warm neutral page background.
 * All colours resolve from the theme's `--edp-*` runtime tokens, so the footer
 * flips with `data-edp-theme` on <html>. All sizes use the theme $sp-* scales.
 * ========================================================================== */

.edp-footer {
    position: relative;
    margin-top: $sp-space-8;
    padding: $sp-space-7 0 $sp-space-5;
    background-color: var(--edp-surface);
    border-top: 1px solid var(--edp-hairline);
    -webkit-backdrop-filter: blur(var(--edp-blur)) saturate(140%);
    backdrop-filter: blur(var(--edp-blur)) saturate(140%);
    color: var(--edp-text-secondary);
}

/* A thin sage hairline along the very top edge — the only accent down here. */
.edp-footer::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 2px;
    background: linear-gradient(
        90deg,
        transparent 0%,
        var(--edp-accent) 30%,
        var(--edp-accent) 70%,
        transparent 100%
    );
    opacity: 0.55;
}

/* ---------------- 1. BRAND -------------------------------------------- */
.edp-footer-brand {
    margin-bottom: $sp-space-5;
}

.edp-footer-wordmark {
    color: var(--edp-text);
    font-size: $sp-text-md;
    font-weight: 700;
    letter-spacing: 0.02em;
    margin: 0 0 $sp-space-2;
}

.edp-footer-tagline {
    color: var(--edp-text-muted);
    font-size: $sp-text-sm;
    line-height: 1.5;
    margin: 0;
    max-width: 34ch;
}

/* ---------------- 2. LINK COLUMNS ------------------------------------- */
.edp-footer-col {
    margin-bottom: $sp-space-5;
}

.edp-footer-col-title {
    color: var(--edp-text);
    font-size: $sp-text-xs;
    font-weight: 700;
    letter-spacing: 0.10em;
    text-transform: uppercase;
    margin: 0 0 $sp-space-3;
}

.edp-footer-list {
    list-style: none;
    margin: 0;
    padding: 0;
}

.edp-footer-list > li {
    margin-bottom: $sp-space-2;
}

.edp-footer-link {
    color: var(--edp-text-secondary);
    font-size: $sp-text-sm;
    text-decoration: none;
    border-radius: var(--edp-radius-sm);
    display: inline-block;
    transition: color 160ms ease, transform 160ms ease;
}

.edp-footer-link:hover,
.edp-footer-link:focus {
    color: var(--edp-accent-ink);
    text-decoration: underline;
    transform: translateX(2px);
}

/* ---------------- 3. LEGAL ------------------------------------------- */
.edp-footer-rule {
    border: 0;
    border-top: 1px solid var(--edp-hairline);
    margin: $sp-space-4 0 $sp-space-4;
}

.edp-footer-fineprint {
    color: var(--edp-text-muted);
    font-size: $sp-text-xs;
    margin: 0;
}

/* ---------------- RESPONSIVE ----------------------------------------- */
@media (max-width: 767px) {
    .edp-footer {
        padding: $sp-space-6 0 $sp-space-4;
        margin-top: $sp-space-6;
    }

    .edp-footer-tagline {
        max-width: none;
    }
}

/* ---------------- REDUCED MOTION ------------------------------------- */
@media (prefers-reduced-motion: reduce) {
    .edp-footer-link {
        transition: none;
    }

    .edp-footer-link:hover,
    .edp-footer-link:focus {
        transform: none;
    }
}

sp_header_footer.script:
/* ==========================================================================
 * Enterprise Digital Portal — FOOTER server script
 * ==========================================================================
 * CRITICAL: NO IIFE wrapper (same rule as the header).
 * Scoped-safe only: `new GlideDateTime()` — NOT `nowDateTime()`.
 *
 * TO CUSTOMISE THE FOOTER LINKS: edit `data.columns` below. The template
 * renders whatever is in this array, so no HTML changes are needed.
 * ========================================================================== */

var portalRecord = $sp.getPortalRecord();

data.portalTitle = portalRecord ? portalRecord.getValue('title') : 'Enterprise Digital';
data.tagline = gs.getMessage('Self-service for the Enterprise Digital delivery programme.');
data.generatedOn = new GlideDateTime().getDisplayValue();
data.copyright = gs.getMessage('{0} Enterprise Digital', new GlideDateTime().getYearLocalTime() + '');

/* --- Footer navigation ---------------------------------------------------- *
 * `url` values are portal-relative (`?id=<pageId>`), so they stay inside the
 * EDP portal. Set `external: true` for off-portal links (adds target=_blank,
 * rel=noopener and an accessible "opens in a new tab" hint).
 * -------------------------------------------------------------------------- */
data.columns = [
    {
        id: 'services',
        title: gs.getMessage('Services'),
        links: [
            { label: gs.getMessage('Service catalog'), url: '?id=sc_landing' },
            { label: gs.getMessage('Change Review Board'), url: '?id=sc_cat_item&sys_id=7518ecedb14542a59ccfc62d5058a8d5' },
            { label: gs.getMessage('Change Deployment'), url: '?id=sc_cat_item&sys_id=9639f638440e4833b8b56ec59845cec4' }
        ]
    },
    {
        id: 'activity',
        title: gs.getMessage('My activity'),
        links: [
            { label: gs.getMessage('My requests'), url: '?id=requests' },
            { label: gs.getMessage('Change Management category'), url: '?id=sc_category&sys_id=89f36964102a4613a251b004e0c8beed' }
        ]
    },
    {
        id: 'help',
        title: gs.getMessage('Help'),
        links: [
            { label: gs.getMessage('Portal home'), url: '?id=x_exls_enterpris_0_edp_home' }
        ]
    }
];
